fn is_odd_at_index_odd(a: &Vec<i32>) -> bool {
    // For every odd index i, check that a[i] is odd.
    // If we find any even number at an odd index, return false.
    for (i, &value) in a.iter().enumerate() {
        if i % 2 == 1 && value % 2 == 0 {
            return false;
        }
    }
    // If no violations found, return true.
    true
}

